extension TokenUsageProvider {
    var brandLogo: [ProviderLogoLayer]? {
        switch self {
        case .claude: return ProviderLogoAssets.claude
        case .codex: return ProviderLogoAssets.openai
        case .antigravity: return ProviderLogoAssets.antigravity
        case .kimi: return ProviderLogoAssets.kimi
        case .cursor: return ProviderLogoAssets.cursor
        case .deepSeek: return ProviderLogoAssets.deepseek
        case .opencode: return ProviderLogoAssets.opencode
        case .codebuddy: return ProviderLogoAssets.codebuddy
        case .workbuddy: return ProviderLogoAssets.workbuddy
        case .grok: return ProviderLogoAssets.grok
        case .zcode: return ProviderLogoAssets.zai
        case .traeCN: return ProviderLogoAssets.trae
        case .qoder: return ProviderLogoAssets.qoder
        case .dsh: return nil
        case .arkCodingPlan: return ProviderLogoAssets.volcengine
        }
    }
}